81	     * would catch it and report an authorization failure as a 500.
82	     *
83	     * @param e The {@link AccessDeniedException} to propagate
84	     * @throws AccessDeniedException always
85	     */
86	    @ExceptionHandler(AccessDeniedException.class)
87	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
88	        throw e;
89	    }
90	
91	    /**
92	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
93	     *
94	     * @param e The {@link Exception} to be handled
95	     * @param request {@link HttpServletRequest} object referring to the current request.
96	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
97	     */
98	    @ExceptionHandler(Exception.class)
99	    @ResponseBody
100	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
101	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
102	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
103	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
104	        return ResponseEntity.status(status).body(detail);
105	    }
106	
107	    /**
108	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
109	     * method returns a 404 Not Found status if an entity does not exist.
110	     *
111	     * @param e The {@link DataIntegrityViolationException} to be handled
112	     * @param request {@link HttpServletRequest} object referring to the current request.
113	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
114	     */
115	    @ExceptionHandler(DataIntegrityViolationException.class)
116	    @ResponseBody
117	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
118	        logger.warn("Data integrity violation at {} {}: {}",
119	            request.getMethod(),
120	            request.getRequestURI(),
121	            e.getMessage());
122	        logger.debug("Data integrity violation stacktrace", e);
123	        HttpStatus status = HttpStatus.NOT_FOUND;
124	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
125	        return ResponseEntity.status(status).body(detail);
126	    }
127	
128	    /**
129	     * Handles exception thrown by Bean Validation on controller methods parameters
130	     *
131	     * @param e The {@link MethodArgumentNotValidException} to be handled
132	     * @param request {@link HttpServletRequest} object referring to the current request.
133	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
134	     */
135	    @ExceptionHandler(MethodArgumentNotValidException.class)
136	    @ResponseBody
137	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
138	        HttpStatus status = HttpStatus.BAD_REQUEST;
139	        BindingErrorsResponse errors = new BindingErrorsResponse();
140	        BindingResult bindingResult = e.getBindingResult();
141	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
142	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
143	            .map(FieldError::getField)
144	            .distinct()
145	            .toList());
146	        if (bindingResult.hasErrors()) {
147	            errors.addAllErrors(bindingResult);
148	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
149	                .map(fieldError -> {
150	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
151	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
152	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
153	                        fieldError.getField(),
154	                        defaultMessage,
155	                        rejectedValue);
156	                    return new ValidationMessageDto(message)
157	                        .putAdditionalProperty("field", fieldError.getField())
158	                        .putAdditionalProperty("rejectedValue", rejectedValue)
159	                        .putAdditionalProperty("defaultMessage", defaultMessage);
160	                })
161	                .toList();
162	            logger.debug("Validation error at {} {}: {}",
163	                request.getMethod(),
164	                request.getRequestURI(),
165	                bindingResult.getFieldErrors());
166	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
167	            return ResponseEntity.status(status).body(detail);
168	        }
169	        return ResponseEntity.status(status).body(detail);
170	    }
171	
172	    /**
173	     * Handles {@link MissingOwnerFieldsException} raised when an owner request omits or
174	     * leaves blank one or more required fields. Returns a 400 Bad Request whose
175	     * {@code errors} array names each offending field.
176	     *
177	     * @param e The {@link MissingOwnerFieldsException} to be handled
178	     * @param request {@link HttpServletRequest} object referring to the current request.
179	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
180	     */
181	    @ExceptionHandler(MissingOwnerFieldsException.class)
182	    @ResponseBody
183	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
184	        HttpStatus status = HttpStatus.BAD_REQUEST;
185	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
186	        detail.setProperty("errors", e.getMissingFields());
187	        return ResponseEntity.status(status).body(detail);
188	    }
189	
190	    /**
191	     * Handles {@link InvalidTelephoneException} raised when an owner request supplies a
192	     * telephone number that is not exactly ten digits after stripping non-digit
193	     * characters. Returns a 400 Bad Request whose {@code errors} array names the
194	     * {@code telephone} field.
195	     *
196	     * @param e The {@link InvalidTelephoneException} to be handled
197	     * @param request {@link HttpServletRequest} object referring to the current request.
198	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
199	     */
200	    @ExceptionHandler(InvalidTelephoneException.class)
201	    @ResponseBody
202	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
203	        HttpStatus status = HttpStatus.BAD_REQUEST;
204	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
205	        detail.setProperty("errors", List.of("telephone"));
206	        return ResponseEntity.status(status).body(detail);
207	    }
208	
209	}
